fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2 + 60;
    let r: i32 = if w < h { w / 2 - 40 } else { h / 2 - 40 };
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 40);
        host::display::state_set(2, 3);
    }
    let seed: i32 = host::display::state_get(2) * 1103515245 + 12345;
    host::display::state_set(2, seed);
    let mut v: i32 = host::display::state_get(1) + ((seed >> 16) & 7) - 3;
    if v < 0 { v = 0; }
    if v > 100 { v = 100; }
    host::display::state_set(1, v);
    host::display::clear(0x0c0c10);
    let mut k: i32 = 0;
    while k < 17 {
        let bv: i32 = k * 100 / 16;
        let col: i32 = if bv < 60 { 0x30b050 } else { if bv < 85 { 0xd0a020 } else { 0xd03030 } };
        let idx: i32 = (24 + k) & 31;
        let x: i32 = cx + sv(idx) * r / 127;
        let y: i32 = cy - sv(idx + 8) * r / 127;
        host::display::fill_rect(x - 6, y - 6, 13, 13, col);
        k = k + 1;
    }
    let na: i32 = (24 + v * 16 / 100) & 31;
    let nx: i32 = cx + sv(na) * (r - 24) / 127;
    let ny: i32 = cy - sv(na + 8) * (r - 24) / 127;
    host::display::draw_line(cx, cy, nx, ny, 0xffffff);
    host::display::fill_rect(cx - 4, cy - 4, 9, 9, 0xffffff);
    host::display::draw_number(cx - 16, cy + 20, v, 0xffffff, 3);
    host::display::draw_string(cx - 70, cy + 52, "GREEN<60 AMBER<85 RED", 0x808080, 1);
    host::display::present();
}
